"""Serialize AF-RES-029 Python sample from preserved first drafts only.

No supplier query, provider navigation, adjudication, or remote mutation occurs here.
"""
from pathlib import Path
import datetime, hashlib, json, re, shutil

B = Path(__file__).parent
PREFIX = 'docs/workstreams/research/AF-RES-029/streams/python/'
NOW = datetime.datetime.now(datetime.timezone.utc).isoformat()

def write_json(path, obj):
    (B/path).write_text(json.dumps(obj, ensure_ascii=False, indent=2)+'\n')

def write_jsonl(path, rows):
    (B/path).write_text(''.join(json.dumps(x, ensure_ascii=False)+'\n' for x in rows))

def load(path):
    return json.loads((B/path).read_text())

def recovery(n):
    p = f'raw/pep-{n:04d}/'
    name = 'earliest-initial-recovery.json' if n in (667,727) else 'initial-pr-recovery.json'
    return load(p+name)

def base(qid,n,kind,period,reason,caller,inputs,outputs,limits,sections):
    r=recovery(n)
    text=(B/r['local_original']).read_text()
    return dict(id=qid,ledger='python',canonical_id=f'pep-{n:04d}',title=r.get('first_title','Supporting Symlinks in Wheels'),whole_or_partial=kind,period=period,
        first_public_date=r['first_public_date'],first_public_date_basis='Opening date of official python/peps PR whose preserved commit history contains the earliest recovered draft; commit authoring date is not asserted to be publication date.',
        first_public_date_evidence=r['first_public_evidence'],first_url=r['fixed_url'],first_version=r['sha'],first_commit_author_date=r['author_date'],
        original_text_path=PREFIX+r['local_original'],original_sha256=r['sha256'],original_git_blob_sha=r['blob_sha'],original_text_sections=sections,
        original=dict(path=PREFIX+r['local_original'],stream_relative_path=r['local_original'],sha256=r['sha256'],git_blob_sha=r['blob_sha'],line_count=len(text.splitlines()),read_sections=sections,source_id=f'PY-{qid}-first'),
        classification_reason=reason,caller=caller,input=inputs,output=outputs,limits=limits,
        first_text_only_rule='Predicates and all three search strings are derived only from this fixed earliest draft. Names present only in later recovery copies do not become first-text knowledge.',
        original_named_families=[],original_named_components=[],whole_must=[],partial_must=[],preferences_and_nonmandatory=[],remaining_integration=[],
        exposure_flags={'current_metadata_status_saved_but_not_read':True,'first_draft_status_read':'Draft','later_main_copy_recovery_exposure': n in (667,686,727),'later_numbered_draft_recovery_exposure':n in (667,727),'later_status_exposure': 'Deferred from 2025 main-copy header' if n==778 else None,'supplier_search_or_supplier_body_read':False,'selection_used_status_or_outcome':False},
        route_execution_started=False,freeze_utc=NOW)

def pred(q,code,statement,section,start,end,inp,failure,inherited=None):
    lines=(B/q['original']['stream_relative_path']).read_text().splitlines()
    d={'id':q['id']+'-'+code,'predicate':statement,'source_positions':[{'source_id':q['original']['source_id'],'section':section,'lines':[start,end],'excerpt':'\n'.join(lines[start-1:end])}], 'falsifying_input':inp,'failure_condition':failure}
    if inherited:d['inherited_from']=[q['id']+'-'+x for x in inherited]
    return d

